import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class MysticMonkeys {
    private final Set<String> labels;

    public MysticMonkeys(Set<String> labels) {
        Set<String> copy = new LinkedHashSet<String>(labels);
        this.labels = Collections.unmodifiableSet(copy);
    }

    public static MysticMonkeys createDefault() {
        Set<String> defaults = new LinkedHashSet<String>();
        defaults.add("Banana");
        defaults.add("Coco");
        defaults.add("Mango");
        return new MysticMonkeys(defaults);
    }

    public boolean isMonkeyLabel(String label) {
        return labels.contains(label);
    }

    public String toListString() {
        List<String> list = new ArrayList<String>(labels);
        return list.toString();
    }

    public Set<String> getLabels() {
        return labels;
    }

    public static void main(String[] args) throws Exception {
        final MysticMonkeys monkeys = MysticMonkeys.createDefault();

        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            Callable<String> task1 = new Callable<String>() {
                @Override
                public String call() {
                    return "Labels: " + monkeys.toListString();
                }
            };

            Callable<String> task2 = new Callable<String>() {
                @Override
                public String call() {
                    List<String> checks = Arrays.asList("Banana", "Coco", "Mango", "Papaya");
                    StringBuilder sb = new StringBuilder();
                    for (int i = 0; i < checks.size(); i++) {
                        String label = checks.get(i);
                        sb.append(label).append("=").append(monkeys.isMonkeyLabel(label));
                        if (i < checks.size() - 1) {
                            sb.append(", ");
                        }
                    }
                    return sb.toString();
                }
            };

            Future<String> future1 = executor.submit(task1);
            Future<String> future2 = executor.submit(task2);

            System.out.println(future1.get());
            System.out.println(future2.get());
        } finally {
            executor.shutdown();
        }
    }
}

