        return tag != null && tags.contains(tag);
    }

    public String asListString() {
        return new ArrayList<String>(tags).toString();
    }

    public Set<String> getTags() {
        return tags;
    }

    public static void main(String[] args) {
        Set<String> initial = new LinkedHashSet<String>(Arrays.asList("Flare", "Glint", "Spark"));
        final StellarSprites sprites = new StellarSprites(initial);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Callable<String> task1 = new Callable<String>() {
            @Override
            public String call() {
                return "All Sprite tags: " + sprites.asListString();
