                for (String check : checks) {
                    results.add(check + "=" + sprites.isSpriteTag(check));
                }
                return "Tag checks: " + results.toString();
            }
        };

        Future<String> future1 = executor.submit(task1);
        Future<String> future2 = executor.submit(task2);

