import java.util.List;
import java.util.Set;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class SolarSquirrels {
    private final List<String> squirrelIdentifiers;
    private final Set<String> squirrelIdentifierSet;

    public SolarSquirrels() {
        List<String> identifiers = Arrays.asList("Nutty", "Whisk", "Fidget");
        this.squirrelIdentifiers = Collections.unmodifiableList(identifiers);
        this.squirrelIdentifierSet = Collections.unmodifiableSet(new HashSet<String>(identifiers));
    }

    public boolean isSquirrel(String identifier) {
        return squirrelIdentifierSet.contains(identifier);
    }

    public String getSquirrelIdentifiers() {
        return squirrelIdentifiers.toString();
    }

    public static void main(String[] args) {
        final SolarSquirrels solarSquirrels = new SolarSquirrels();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Callable<Boolean> checkTask = new Callable<Boolean>() {
            @Override
            public Boolean call() {
                return solarSquirrels.isSquirrel("Whisk");
            }
        };

        Callable<String> listTask = new Callable<String>() {
            @Override
            public String call() {
                return solarSquirrels.getSquirrelIdentifiers();
            }
        };

        try {
            Future<Boolean> checkResult = executor.submit(checkTask);
            Future<String> listResult = executor.submit(listTask);

            System.out.println(checkResult.get());
            System.out.println(listResult.get());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } catch (ExecutionException e) {
            throw new RuntimeException(e);
        } finally {
            executor.shutdown();
        }
    }
}
