import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.locks.ReentrantLock;

public class DeadlockAvoidanceSwapProgram {

    public static void main(String[] args) throws Exception {
        final Container containerA = new Container("A", 100);
        final Container containerB = new Container("B", 50);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Callable<String> task1 = new Callable<String>() {
            @Override
            public String call() {
                try {
                    boolean result = swap(containerA, containerB, 30, 3, TimeUnit.SECONDS);
                    return Thread.currentThread().getName() + " swap A->B result=" + result + " " + containerA + " " + containerB;
                } catch (InsufficientElementsException e) {
                    return Thread.currentThread().getName() + " swap A->B failed: " + e.getMessage() + " " + containerA + " " + containerB;
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return Thread.currentThread().getName() + " interrupted";
                }
            }
        };

        Callable<String> task2 = new Callable<String>() {
            @Override
            public String call() {
                try {
                    boolean result = swap(containerB, containerA, 40, 3, TimeUnit.SECONDS);
                    return Thread.currentThread().getName() + " swap B->A result=" + result + " " + containerA + " " + containerB;
                } catch (InsufficientElementsException e) {
                    return Thread.currentThread().getName() + " swap B->A failed: " + e.getMessage() + " " + containerA + " " + containerB;
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return Thread.currentThread().getName() + " interrupted";
                }
            }
        };

        List<Future<String>> futures = new ArrayList<Future<String>>();
        futures.add(executor.submit(task1));
        futures.add(executor.submit(task2));

        for (Future<String> future : futures) {
            System.out.println(future.get());
        }

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Final state: " + containerA + " " + containerB);
    }

    public static boolean swap(Container origin,
                               Container target,
                               int elementsToSwap,
                               long timeout,
                               TimeUnit unit)
            throws InterruptedException, InsufficientElementsException {

        if (origin == null || target == null) {
            throw new IllegalArgumentException("Containers must not be null");
        }
        if (origin == target) {
            throw new IllegalArgumentException("Origin and target must be different containers");
