            lock.unlock();
        }

        public int getWidgetCount() {
            return widgets.get();
        }

        public void addWidgets(int amount) {
            widgets.add(amount);
        }

        public void removeWidgets(int amount) {
            widgets.subtract(amount);
        }

        @Override
        public String toString() {
            return "Bin{name='" + name + "', widgets=" + widgets + "}";
        }
    }

    public static class NotEnoughWidgetsException extends Exception {
        public NotEnoughWidgetsException(String message) {
            super(message);
        }
    }
