import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class PersonSet {
    private final Set<Person> mySet = new HashSet<Person>();

    public synchronized void addPerson(Person person) {
        mySet.add(person);
    }

    public synchronized boolean containsPerson(Person person) {
        return mySet.contains(person);
    }

    public interface Person {
    }

    static class SimplePerson implements Person {
        private final String name;
        private final int id;

        SimplePerson(String name, int id) {
            this.name = name;
            this.id = id;
        }

        public String getName() {
            return name;
        }

        public int getId() {
            return id;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) {
                return true;
            }
            if (!(obj instanceof SimplePerson)) {
                return false;
            }
            SimplePerson other = (SimplePerson) obj;
            if (id != other.id) {
                return false;
            }
            if (name == null) {
                return other.name == null;
            }
            return name.equals(other.name);
        }

        @Override
        public int hashCode() {
            int result = 17;
            result = 31 * result + id;
            result = 31 * result + (name == null ? 0 : name.hashCode());
            return result;
        }

        @Override
        public String toString() {
            return "SimplePerson{name='" + name + "', id=" + id + "}";
        }
    }

    public static void main(String[] args) throws Exception {
        final PersonSet personSet = new PersonSet();
        final SimplePerson alice = new SimplePerson("Alice", 1);
        final SimplePerson bob = new SimplePerson("Bob", 2);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Future<?> addTask = executor.submit(new Runnable() {
            @Override
            public void run() {
                personSet.addPerson(alice);
                personSet.addPerson(bob);
            }
        });

        Future<Boolean> containsTask = executor.submit(new java.util.concurrent.Callable<Boolean>() {
            @Override
            public Boolean call() throws Exception {
                addTask.get();
                return personSet.containsPerson(alice) && personSet.containsPerson(bob);
            }
        });

        System.out.println(containsTask.get());

        executor.shutdown();
    }
}

