import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class PublishingVehicleTracker {
    private final ConcurrentMap<String, SafePoint> locations;
    private final Map<String, SafePoint> unmodifiableMap;

    public PublishingVehicleTracker(Map<String, SafePoint> initialLocations) {
        if (initialLocations == null) {
            throw new NullPointerException("initialLocations");
        }
        this.locations = new ConcurrentHashMap<String, SafePoint>();
        for (Map.Entry<String, SafePoint> entry : initialLocations.entrySet()) {
            if (entry.getKey() == null || entry.getValue() == null) {
                throw new NullPointerException("vehicle id and point must not be null");
            }
            int[] coords = entry.getValue().get();
            this.locations.put(entry.getKey(), new SafePoint(coords[0], coords[1]));
        }
        this.unmodifiableMap = Collections.unmodifiableMap(this.locations);
    }

    public Map<String, SafePoint> getLocations() {
        return unmodifiableMap;
    }

    public SafePoint getLocation(String id) {
        if (id == null) {
            throw new NullPointerException("id");
        }
        return locations.get(id);
    }

    public void setLocation(String id, int x, int y) {
        if (id == null) {
            throw new NullPointerException("id");
        }
        SafePoint point = locations.get(id);
        if (point == null) {
            throw new IllegalArgumentException("No such vehicle: " + id);
        }
        point.set(x, y);
    }

    public static void main(String[] args) {
        Map<String, SafePoint> initial = new HashMap<String, SafePoint>();
        initial.put("V1", new SafePoint(0, 0));
        initial.put("V2", new SafePoint(10, 10));
        initial.put("V3", new SafePoint(20, 20));

        final PublishingVehicleTracker tracker = new PublishingVehicleTracker(initial);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable updater1 = new Runnable() {
            @Override
            public void run() {
                for (int i = 1; i <= 5; i++) {
                    tracker.setLocation("V1", i, i * 2);
                    sleep(50);
                }
            }
        };

        Runnable updater2 = new Runnable() {
            @Override
            public void run() {
                for (int i = 1; i <= 5; i++) {
                    tracker.setLocation("V2", 10 + i, 10 + i * 3);
                    sleep(50);
                }
            }
        };

        executor.submit(updater1);
        executor.submit(updater2);

        executor.shutdown();
        try {
            executor.awaitTermination(5, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        Map<String, SafePoint> locations = tracker.getLocations();
        for (Map.Entry<String, SafePoint> entry : locations.entrySet()) {
            int[] coords = entry.getValue().get();
            System.out.println(entry.getKey() + " -> (" + coords[0] + ", " + coords[1] + ")");
        }

        try {
            tracker.setLocation("UNKNOWN", 1, 1);
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }

    private static void sleep(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

