import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class MysticBeastTracker {
    private final ConcurrentMap<String, Glyph> perches;

    public MysticBeastTracker(Map<String, Glyph> initialPerches) {
        this.perches = new ConcurrentHashMap<>();
        if (initialPerches != null) {
            for (Map.Entry<String, Glyph> entry : initialPerches.entrySet()) {
                String sigil = entry.getKey();
                Glyph glyph = entry.getValue();
                if (sigil != null && glyph != null) {
                    this.perches.put(sigil, glyph);
                }
            }
        }
    }

    public Map<String, Glyph> getPerches() {
        return Collections.unmodifiableMap(perches);
    }

    public Glyph getPerch(String sigil) {
        return perches.get(sigil);
    }

    public void setPerch(String sigil, int spark, int glimmer) {
        Glyph updated = perches.computeIfPresent(sigil, new java.util.function.BiFunction<String, Glyph, Glyph>() {
            @Override
            public Glyph apply(String s, Glyph oldGlyph) {
                return new Glyph(spark, glimmer);
            }
        });
        if (updated == null) {
            throw new IllegalArgumentException("Beast with sigil '" + sigil + "' does not exist.");
        }
    }

    public Map<String, Glyph> getPerchesAsStatic() {
        return Collections.unmodifiableMap(new HashMap<String, Glyph>(perches));
    }

    public static void main(String[] args) throws Exception {
        Map<String, Glyph> initial = new HashMap<String, Glyph>();
        initial.put("Aetherwing", new Glyph(1, 1));
        initial.put("Stormclaw", new Glyph(2, 3));
        initial.put("Moonscale", new Glyph(5, 8));

        final MysticBeastTracker tracker = new MysticBeastTracker(initial);

        ExecutorService executor = Executors.newFixedThreadPool(4);

        Callable<Void> task1 = new Callable<Void>() {
            @Override
            public Void call() {
                tracker.setPerch("Aetherwing", 10, 20);
                return null;
            }
        };

        Callable<Void> task2 = new Callable<Void>() {
            @Override
            public Void call() {
                tracker.setPerch("Stormclaw", 30, 40);
                return null;
            }
        };

        Callable<Glyph> task3 = new Callable<Glyph>() {
            @Override
            public Glyph call() {
                return tracker.getPerch("Moonscale");
            }
        };

        Callable<Map<String, Glyph>> task4 = new Callable<Map<String, Glyph>>() {
            @Override
            public Map<String, Glyph> call() {
                return tracker.getPerchesAsStatic();
            }
        };

        Future<Void> f1 = executor.submit(task1);
        Future<Void> f2 = executor.submit(task2);
        Future<Glyph> f3 = executor.submit(task3);
        Future<Map<String, Glyph>> f4 = executor.submit(task4);

        f1.get();
        f2.get();
        Glyph moonscalePerch = f3.get();
        Map<String, Glyph> snapshot = f4.get();

        System.out.println("Moonscale perch: " + moonscalePerch);
        System.out.println("Snapshot: " + snapshot);
        System.out.println("Live view: " + tracker.getPerches());

        executor.shutdown();
    }
}

