public class DreamWeaver {
    private final FutureTask<Vision> futureTask;
    private final Thread worker;
    private volatile boolean started;

    public DreamWeaver() {
        this.futureTask = new FutureTask<Vision>(new Callable<Vision>() {
            @Override
            public Vision call() throws VisionCastException {
                return loadVision();
            }
        });
        this.worker = new Thread(futureTask, "DreamWeaver-Worker");
        this.started = false;
    }

    public Vision loadVision() throws VisionCastException {
        try {
            Thread.sleep(1000L);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new VisionCastException("Vision summoning interrupted", e);
        }
        return new SimpleVision("A luminous vision emerges from the void.");
    }

    public synchronized void start() {
        if (!started) {
            started = true;
            worker.start();
        }
    }

    public Vision get() throws VisionCastException, InterruptedException {
        try {
            return futureTask.get();
        } catch (ExecutionException e) {
            Throwable cause = e.getCause();
            if (cause instanceof VisionCastException) {
                throw (VisionCastException) cause;
            }
            throw launderThrowable(cause);
        }
    }

    private RuntimeException launderThrowable(Throwable t) {
        if (t instanceof RuntimeException) {
            return (RuntimeException) t;
        }
        if (t instanceof Error) {
            throw (Error) t;
        }
        return new IllegalStateException("Unchecked exception during vision summoning", t);
    }

    public static void main(String[] args) {
        DreamWeaver dreamWeaver = new DreamWeaver();
        dreamWeaver.start();

        try {
            Vision vision = dreamWeaver.get();
            System.out.println(vision);
        } catch (VisionCastException e) {
            System.err.println("VisionCastException: " + e.getMessage());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Interrupted while awaiting vision");
        }
    }
}

