import java.util.concurrent.Callable;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class EnchantmentProgram {

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            Enchanter<Integer> enchanter = new IntegerEnchanter();

            List<Talisman<Integer>> talismans = Arrays.<Talisman<Integer>>asList(
                    new BasicTalisman<Integer>(1),
                    new BasicTalisman<Integer>(2),
                    new BasicTalisman<Integer>(3),
                    new BasicTalisman<Integer>(4),
                    new BasicTalisman<Integer>(5)
            );

            List<Integer> sequentialTalismans = enchanter.weaveSequential(talismans);
            List<Integer> parallelTalismans = enchanter.weaveParallel(talismans, executor);

            SigilNode<Integer> grove =
                    new BasicSigilNode<Integer>(
                            10,
                            Arrays.<SigilNode<Integer>>asList(
                                    new BasicSigilNode<Integer>(
                                            20,
                                            Arrays.<SigilNode<Integer>>asList(
                                                    new BasicSigilNode<Integer>(30, Collections.<SigilNode<Integer>>emptyList()),
                                                    new BasicSigilNode<Integer>(40, Collections.<SigilNode<Integer>>emptyList())
                                            )
                                    ),
                                    new BasicSigilNode<Integer>(
                                            50,
                                            Arrays.<SigilNode<Integer>>asList(
                                                    new BasicSigilNode<Integer>(60, Collections.<SigilNode<Integer>>emptyList())
                                            )
                                    )
                            )
                    );

            List<Integer> sequentialSigils = enchanter.weaveRecursiveSequential(grove);
            List<Integer> parallelSigils = enchanter.weaveRecursiveParallel(grove, executor);

            System.out.println(sequentialTalismans);
            System.out.println(parallelTalismans);
            System.out.println(sequentialSigils);
            System.out.println(parallelSigils);
        } finally {
            executor.shutdown();
        }
    }
}

interface Talisman<R> {
    R enchant();
}

interface SigilNode<R> {
    R compute();
    List<SigilNode<R>> getChildren();
}

class Enchanter<R> {

    public List<R> weaveSequential(List<? extends Talisman<? extends R>> talismans) {
        List<R> results = new ArrayList<R>();
        for (Talisman<? extends R> talisman : talismans) {
            results.add(talisman.enchant());
        }
        return results;
    }

    public List<R> weaveParallel(List<? extends Talisman<? extends R>> talismans, ExecutorService executor) {
        List<Future<R>> futures = new ArrayList<Future<R>>();
        for (final Talisman<? extends R> talisman : talismans) {
            futures.add(executor.submit(new Callable<R>() {
                @Override
                public R call() {
                    return talisman.enchant();
                }
            }));
        }
        List<R> results = new ArrayList<R>();
        for (Future<R> future : futures) {
            results.add(getUnchecked(future));
        }
        return results;
    }

    public List<R> weaveRecursiveSequential(SigilNode<? extends R> root) {
        List<R> results = new ArrayList<R>();
        weaveRecursiveSequentialInternal(root, results);
        return results;
    }

    private void weaveRecursiveSequentialInternal(SigilNode<? extends R> node, List<R> results) {
        results.add(node.compute());
        for (SigilNode<? extends R> child : node.getChildren()) {
            weaveRecursiveSequentialInternal(child, results);
