import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class MysticCounter {
    private int essence;

    public MysticCounter(int initialEssence) {
        this.essence = initialEssence;
    }

    public synchronized int get() {
        return essence;
    }

    public synchronized int compareAndSwap(int expectedEssence, int newEssence) {
        int oldEssence = essence;
        if (oldEssence == expectedEssence) {
            essence = newEssence;
        }
        return oldEssence;
    }

    public synchronized boolean compareAndSet(int expectedEssence, int newEssence) {
        return compareAndSwap(expectedEssence, newEssence) == expectedEssence;
    }

    public static void main(String[] args) throws Exception {
        final MysticCounter counter = new MysticCounter(0);

        ExecutorService executor = Executors.newFixedThreadPool(1);

        Future<?> future = executor.submit(new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < 5; i++) {
                    while (true) {
                        int current = counter.get();
                        if (counter.compareAndSet(current, current + 1)) {
                            break;
                        }
                    }
                }
            }
        });

        for (int i = 0; i < 5; i++) {
            while (true) {
                int current = counter.get();
                if (counter.compareAndSet(current, current + 1)) {
                    break;
                }
            }
        }

        future.get();
        executor.shutdown();

        System.out.println(counter.get());
    }
}

