import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

/**
 * Immutable holder for a robot's (x, y) coordinates.
 */
class RobotCoordinates {
    private final int x;
    private final int y;

    public RobotCoordinates(int x, int y) {
        this.x = x;
        this.y = y;
    }

    /** Returns the X coordinate. */
    public int getX() {
        return x;
    }

    /** Returns the Y coordinate. */
    public int getY() {
        return y;
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}

/**
 * Thread‑safe tracker that delegates all state handling to a ConcurrentHashMap.
 */
class DelegatingRobotTracker {
    /** The underlying concurrent map – the only mutable state. */
    private final ConcurrentHashMap<String, RobotCoordinates> robotMap;

    /**
     * Constructs the tracker with an initial set of robot IDs and coordinates.
     *
     * @param initialCoordinates a map containing the starting positions; the map is copied.
     */
    public DelegatingRobotTracker(Map<String, RobotCoordinates> initialCoordinates) {
        this.robotMap = new ConcurrentHashMap<>(initialCoordinates);
    }

    /**
     * Returns the coordinates of the robot with the given id, or {@code null} if absent.
     */
    public RobotCoordinates getRobotCoordinates(String robotId) {
        return robotMap.get(robotId);
    }

    /**
     * Updates the coordinates of an existing robot.
     *
     * @param robotId        the id of the robot to update
     * @param newCoordinates the new position
     * @return {@code true} if the robot existed and was updated; {@code false} otherwise
     */
    public boolean updateRobotCoordinates(String robotId, RobotCoordinates newCoordinates) {
        // computeIfPresent updates only when the key is already present
        return robotMap.computeIfPresent(robotId, (k, v) -> newCoordinates) != null;
    }

    /**
     * Returns a **live** unmodifiable view of the underlying map.
     * Any subsequent changes to the tracker are reflected in this view.
     */
    public Map<String, RobotCoordinates> getAllRobotCoordinatesLive() {
        return Collections.unmodifiableMap(robotMap);
    }

    /**
     * Returns a **snapshot** of the current state – a new map that will not change
     * even if the tracker is later modified.
     */
    public Map<String, RobotCoordinates> getAllRobotCoordinatesSnapshot() {
        // Copy the entries into a regular HashMap and wrap it
        return Collections.unmodifiableMap(new HashMap<>(robotMap));
    }
}

/**
 * Entry point – demonstrates concurrent usage of DelegatingRobotTracker.
 */
public class Main {
    public static void main(String[] args) throws InterruptedException {
        // -----------------------------------------------------------------
        // 1️⃣  Build the initial data (Java 8 compatible – no Map.of)
        // -----------------------------------------------------------------
        Map<String, RobotCoordinates> initial = new HashMap<>();
        initial.put("R1", new RobotCoordinates(0, 0));
        initial.put("R2", new RobotCoordinates(5, 5));
        initial.put("R3", new RobotCoordinates(10, -3));

        // -----------------------------------------------------------------
        // 2️⃣  Create the tracker
        // -----------------------------------------------------------------
        final DelegatingRobotTracker tracker = new DelegatingRobotTracker(initial);

        // -----------------------------------------------------------------
        // 3️⃣  Set up a fixed thread pool with **exactly 2** worker threads
        // -----------------------------------------------------------------
        ExecutorService pool = Executors.newFixedThreadPool(2);

        // -----------------------------------------------------------------
        // 4️⃣  Submit a few concurrent tasks
        // -----------------------------------------------------------------
        // Task A – try to move R1
        pool.submit(new Runnable() {
            @Override
            public void run() {
                RobotCoordinates newPos = new RobotCoordinates(1, 1);
                boolean ok = tracker.updateRobotCoordinates("R1", newPos);
                System.out.println("[Task A] Update R1 to " + newPos + " -> " + ok);
            }
        });

        // Task B – try to move a non‑existent robot (should fail)
        pool.submit(new Runnable() {
            @Override
            public void run() {
                RobotCoordinates newPos = new RobotCoordinates(99, 99);
                boolean ok = tracker.updateRobotCoordinates("R99", newPos);
                System.out.println("[Task B] Update R99 to " + newPos + " -> " + ok);
            }
        });

        // Task C – read a live view while other tasks may still be running
        pool.submit(new Runnable() {
            @Override
            public void run() {
                Map<String, RobotCoordinates> live = tracker.getAllRobotCoordinatesLive();
                System.out.println("[Task C] Live view: " + live);
            }
        });

        // -----------------------------------------------------------------
        // 5️⃣  Shut down the pool and wait for tasks to finish
        // -----------------------------------------------------------------
        pool.shutdown();
        pool.awaitTermination(2, TimeUnit.SECONDS);

        // -----------------------------------------------------------------
        // 6️⃣  After all concurrent work, show the snapshot view
        // -----------------------------------------------------------------
        Map<String, RobotCoordinates> snapshot = tracker.getAllRobotCoordinatesSnapshot();
        System.out.println("[Main] Snapshot view after tasks: " + snapshot);

        // -----------------------------------------------------------------
        // 7️⃣  Direct single‑threaded checks
        // -----------------------------------------------------------------
        System.out.println("[Main] R2 coordinates: " + tracker.getRobotCoordinates("R2"));
        System.out.println("[Main] R3 coordinates: " + tracker.getRobotCoordinates("R3"));
    }
}

