import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;
import java.util.Random;

public class DeadlockAvoidance {
    static class NotEnoughItemsException extends Exception {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }

    static class ParcelCount {
        int count;

        public ParcelCount(int count) {
            this.count = count;
        }
    }

    static class Locker {
        String name;
        ParcelCount parcelCount;
        ReentrantLock lock;

        public Locker(String name, ParcelCount parcelCount) {
            this.name = name;
            this.parcelCount = parcelCount;
            this.lock = new ReentrantLock();
        }
    }

    private static final Random random = new Random();

    public static boolean move(Locker source, Locker target, int quantity, long timeout, TimeUnit unit) {
        long nanosTimeout = unit.toNanos(timeout);
        long startTime = System.nanoTime();

        while (true) {
            if (source.lock.tryLock() && target.lock.tryLock()) {
                try {
                    if (source.parcelCount.count >= quantity) {
                        source.parcelCount.count -= quantity;
                        target.parcelCount.count += quantity;
                        return true;
                    } else {
                        throw new NotEnoughItemsException("Not enough items in source locker");
                    }
                } finally {
                    target.lock.unlock();
                    source.lock.unlock();
                }
            } else {
                long elapsed = System.nanoTime() - startTime;
                if (elapsed >= nanosTimeout) {
                    return false;
                }
                try {
                    long delay = calculateDelay();
                    TimeUnit.NANOSECONDS.sleep(delay);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return false;
                }
            }
        }
    }

    private static long calculateDelay() {
        long fixedDelay = 100_000; // 100ms
        long randomDelay = random.nextInt(100_000); // 0-100ms
        return fixedDelay + randomDelay;
    }

    public static void main(String[] args) {
        ParcelCount parcelCount1 = new ParcelCount(10);
        ParcelCount parcelCount2 = new ParcelCount(5);

        Locker locker1 = new Locker("Locker1", parcelCount1);
        Locker locker2 = new Locker("Locker2", parcelCount2);

        Runnable moveTask = () -> {
            try {
                boolean moved = move(locker1, locker2, 3, 1, TimeUnit.SECONDS);
                System.out.println("Moved: " + moved);
            } catch (NotEnoughItemsException e) {
                System.out.println(e.getMessage());
            }
        };

        Thread thread = new Thread(moveTask);
        thread.start();

        try {
            thread.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Locker1 parcels: " + locker1.parcelCount.count);
        System.out.println("Locker2 parcels: " + locker2.parcelCount.count);
    }
}

