import java.util.Random;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class DeadlockAvoidance {
    static class InsufficientElementsException extends Exception {
        InsufficientElementsException(String message) {
            super(message);
        }
    }

    static class ElementCount {
        int count;

        ElementCount(int count) {
            this.count = count;
        }
    }

    static class Container {
        private final ElementCount elementCount;
        private final ReentrantLock lock = new ReentrantLock();

        Container(ElementCount elementCount) {
            this.elementCount = elementCount;
        }

        ReentrantLock getLock() {
            return lock;
        }

        ElementCount getElementCount() {
            return elementCount;
        }
    }

    private static final Random RANDOM = new Random();

    public static boolean swap(Container origin, Container target, int numElements,
                               long timeout, TimeUnit unit) throws InsufficientElementsException {
        long timeoutNanos = unit.toNanos(timeout);
        long start = System.nanoTime();

        while (System.nanoTime() - start < timeoutNanos) {
            long remaining = timeoutNanos - (System.nanoTime() - start);
            if (remaining <= 0) break;

            boolean originLocked = false;
            boolean targetLocked = false;
            try {
                originLocked = origin.getLock().tryLock(remaining, TimeUnit.NANOSECONDS);
                if (!originLocked) continue;

                remaining = timeoutNanos - (System.nanoTime() - start);
                if (remaining <= 0) continue;

                targetLocked = target.getLock().tryLock(remaining, TimeUnit.NANOSECONDS);
                if (!targetLocked) continue;

                if (origin.getElementCount().count >= numElements) {
                    origin.getElementCount().count -= numElements;
                    target.getElementCount().count += numElements;
                    return true;
                } else {
                    throw new InsufficientElementsException("Insufficient elements in origin container");
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            } finally {
                if (targetLocked) target.getLock().unlock();
                if (originLocked) origin.getLock().unlock();
            }

            try {
                Thread.sleep(getFixedDelay() + getRandomDelay());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            }
        }
        return false;
    }

    private static long getFixedDelay() {
        return 1; // milliseconds
    }

    private static long getRandomDelay() {
        return RANDOM.nextInt(10); // milliseconds
    }

    public static void main(String[] args) throws Exception {
        Container origin = new Container(new ElementCount(10));
        Container target = new Container(new ElementCount(0));

        Thread worker = new Thread(() -> {
            try {
                boolean result = swap(origin, target, 5, 2, TimeUnit.SECONDS);
                System.out.println(result
                        ? "Swap succeeded. Origin: " + origin.getElementCount().count + ", Target: " + target.getElementCount().count
                        : "Swap failed due to timeout.");
            } catch (InsufficientElementsException e) {
                System.out.println("Swap failed: " + e.getMessage());
            }
        });

        worker.start();
        worker.join();
    }
}

