import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import java.util.Random;

public class WidgetMover {
    private static final Random RANDOM = new Random();

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        Bin binA = new Bin(20);
        Bin binB = new Bin(0);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Callable<Boolean> task1 = () -> moveWidgets(binA, binB, 10, 3, TimeUnit.SECONDS);
        Callable<Boolean> task2 = () -> moveWidgets(binB, binA, 5, 3, TimeUnit.SECONDS);

        Future<Boolean> f1 = executor.submit(task1);
        Future<Boolean> f2 = executor.submit(task2);

        System.out.println("Task1 result: " + f1.get());
        System.out.println("Task2 result: " + f2.get());

        System.out.println("BinA widgets: " + binA.getWidgetCount().getCount());
        System.out.println("BinB widgets: " + binB.getWidgetCount().getCount());

        executor.shutdown();
    }

    public static boolean moveWidgets(Bin source, Bin target, int widgets, long timeout, TimeUnit unit) {
        long timeoutNanos = unit.toNanos(timeout);
        long deadline = System.nanoTime() + timeoutNanos;
        ReentrantLock srcLock = source.getLock();
        ReentrantLock tgtLock = target.getLock();

        while (System.nanoTime() < deadline) {
            long remaining = deadline - System.nanoTime();
            try {
                if (srcLock.tryLock(remaining, TimeUnit.NANOSECONDS)) {
                    try {
                        remaining = deadline - System.nanoTime();
                        if (tgtLock.tryLock(remaining, TimeUnit.NANOSECONDS)) {
                            try {
                                if (source.getWidgetCount().getCount() >= widgets) {
                                    source.getWidgetCount().decrease(widgets);
                                    target.getWidgetCount().increase(widgets);
                                    return true;
                                } else {
                                    throw new NotEnoughWidgetsException("Insufficient widgets in source bin");
                                }
                            } finally {
                                tgtLock.unlock();
                            }
                        }
                    } finally {
                        srcLock.unlock();
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            }

            pauseBeforeRetry();
        }
        return false;
    }

    private static void pauseBeforeRetry() {
        try {
            Thread.sleep(fixedDelayMillis() + randomDelayMillis());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private static long fixedDelayMillis() {
        return 10L;
    }

    private static long randomDelayMillis() {
        return RANDOM.nextInt(10);
    }

    static class Bin {
        private final ReentrantLock lock = new ReentrantLock();
        private final WidgetCount widgetCount;

        Bin(int initial) {
            this.widgetCount = new WidgetCount(initial);
        }

        ReentrantLock getLock() {
            return lock;
        }

        WidgetCount getWidgetCount() {
            return widgetCount;
        }
    }

    static class WidgetCount {
        private int count;

        WidgetCount(int count) {
            this.count = count;
        }

        int getCount() {
            return count;
        }

        void increase(int amount) {
            count += amount;
        }

        void decrease(int amount) {
            count -= amount;
        }
    }

    static class NotEnoughWidgetsException extends RuntimeException {
        NotEnoughWidgetsException(String message) {
            super(message);
        }
    }
}

