import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

class SafePoint {
    private final double x;
    private final double y;

    public SafePoint(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public double getX() {
        return x;
    }

    public double getY() {
        return y;
    }
}

class PublishingVehicleTracker {
    private final ReadWriteLock lock = new ReentrantReadWriteLock();
    private final Lock readLock = lock.readLock();
    private final Lock writeLock = lock.writeLock();
    private final Map<String, SafePoint> vehicleCoordinates = new HashMap<>();

    public Map<String, SafePoint> getVehicleCoordinates() {
        readLock.lock();
        try {
            return java.util.Collections.unmodifiableMap(new HashMap<>(vehicleCoordinates));
        } finally {
            readLock.unlock();
        }
    }

    public SafePoint getVehicleCoordinate(String vehicleId) {
        readLock.lock();
        try {
            return vehicleCoordinates.get(vehicleId);
        } finally {
            readLock.unlock();
        }
    }

    public void updateVehicleCoordinate(String vehicleId, double x, double y) {
        writeLock.lock();
        try {
            if (!vehicleCoordinates.containsKey(vehicleId)) {
                throw new RuntimeException("Vehicle not found");
            }
            vehicleCoordinates.put(vehicleId, new SafePoint(x, y));
        } finally {
            writeLock.unlock();
        }
    }

    public void addVehicle(String vehicleId, double x, double y) {
        writeLock.lock();
        try {
            vehicleCoordinates.put(vehicleId, new SafePoint(x, y));
        } finally {
            writeLock.unlock();
        }
    }
}

