}

enum Resonance {
    POSITIVE, NEGATIVE
}

class Rune {
    private final Constellation constellation;
    private final Resonance resonance;

    public Rune(Constellation constellation, Resonance resonance) {
        this.constellation = constellation;
        this.resonance = resonance;
    }

    public Constellation getConstellation() {
        return constellation;
    }

    public Resonance getResonance() {
        return resonance;
    }
}

class Harmony {
    private final Rune rune1;
    private final Rune rune2;

    public Harmony(Rune rune1, Rune rune2) {
        this.rune1 = rune1;
        this.rune2 = rune2;
    }

    public Rune getRune1() {
        return rune1;
    }

    public Rune getRune2() {
        return rune2;
    }
}

class Grimoire {
    private final List<Harmony> harmonies = new ArrayList<>();

    public void addHarmony(Harmony harmony) {
        harmonies.add(harmony);
    }

    public List<Harmony> getHarmonies() {
        return Collections.unmodifiableList(harmonies);
    }
}

public class Main {
    public static int channelTheGrimoire(Collection<Rune> candidates, Grimoire grimoire) {
        List<Rune> sorted = new ArrayList<>(candidates);
        sorted.sort(Comparator.comparing(Rune::getConstellation)
                .thenComparing(Rune::getResonance));

        int count = 0;
        for (int i = 0; i < sorted.size() - 1; ) {
            Rune a = sorted.get(i);
