import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

class Starlight {
    private final int shimmer;
    private final int pulse;

    public Starlight(int shimmer, int pulse) {
        this.shimmer = shimmer;
        this.pulse = pulse;
    }

    public int getShimmer() {
        return shimmer;
    }

    public int getPulse() {
        return pulse;
    }

    @Override
    public String toString() {
        return "Starlight{" +
                "shimmer=" + shimmer +
                ", pulse=" + pulse +
                '}';
    }
}

public class CelestialCaravanTracker {
    private final ConcurrentHashMap<String, Starlight> havens;

    public CelestialCaravanTracker(Map<String, Starlight> initialHavens) {
        this.havens = new ConcurrentHashMap<>(initialHavens);
    }

    public Map<String, Starlight> getHavens() {
        return java.util.Collections.unmodifiableMap(havens);
    }

    public Starlight getHaven(String glyph) {
        return havens.get(glyph);
    }

    public void setHaven(String glyph, int shimmer, int pulse) {
        if (!havens.containsKey(glyph)) {
            throw new IllegalArgumentException("Beast with glyph '" + glyph + "' does not exist.");
        }
        havens.put(glyph, new Starlight(shimmer, pulse));
    }

    public Map<String, Starlight> getHavensAsStatic() {
        return havens.entrySet().stream()
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        e -> new Starlight(e.getValue().getShimmer(), e.getValue().getPulse()),
                        (e1, e2) -> e1,
                        java.util.Collections::unmodifiableMap
                ));
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, Starlight> initialHavens = Map.of(
                "Glyph1", new Starlight(10, 20),
                "Glyph2", new Starlight(30, 40)
        );

        CelestialCaravanTracker tracker = new CelestialCaravanTracker(initialHavens);

        ExecutorService executor = Executors.newFixedThreadPool(5);

        Runnable task1 = () -> System.out.println("Haven for Glyph1: " + tracker.getHaven("Glyph1"));
        Runnable task2 = () -> tracker.setHaven("Glyph1", 50, 60);
        Runnable task3 = () -> System.out.println("Updated Haven for Glyph1: " + tracker.getHaven("Glyph1"));
        Runnable task4 = () -> System.out.println("All Havens: " + tracker.getHavens());
        Runnable task5 = () -> System.out.println("Static Havens: " + tracker.getHavensAsStatic());

        executor.execute(task1);
        executor.execute(task2);
        executor.execute(task3);
        executor.execute(task4);
        executor.execute(task5);

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.SECONDS);
    }
}

