import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Future;
import java.util.concurrent.FutureTask;

interface Vision {
}

class VisionCastException extends Exception {
    public VisionCastException(String message) {
        super(message);
    }

    public VisionCastException(String message, Throwable cause) {
        super(message, cause);
    }
}

public class DreamWeaver {
    private final Future<Vision> future;

    public DreamWeaver() {
        Callable<Vision> callable = this::loadVision;
        this.future = new FutureTask<>(callable);
    }

    public void start() {
        Thread thread = new Thread((Runnable) future);
        thread.start();
    }

    public Vision get() throws VisionCastException {
        try {
            return future.get();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new VisionCastException("Interrupted while waiting for vision", e);
        } catch (ExecutionException e) {
            Throwable cause = e.getCause();
            if (cause instanceof VisionCastException) {
                throw (VisionCastException) cause;
            } else {
                throw new VisionCastException("Unexpected error while summoning vision", cause);
            }
        }
    }

    private Vision loadVision() throws VisionCastException {
        try {
            Thread.sleep(1000); // Simulate work
            return new Vision() {};
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new VisionCastException("Interrupted while loading vision", e);
        }
    }

    public static void main(String[] args) {
        DreamWeaver dreamWeaver = new DreamWeaver();
        dreamWeaver.start();

        try {
            Vision vision = dreamWeaver.get();
            System.out.println("Vision summoned successfully");
        } catch (VisionCastException e) {
            System.out.println("Failed to summon vision: " + e.getMessage());
        }
    }
}

