class CrystalTransferHelper {
    private static final ReentrantLock tieBreaker = new ReentrantLock();

    void transfer(VaultNode from, VaultNode to, int amount) throws InsufficientCrystalsException {
        VaultNode first, second;
        int hFrom = from.identityHash();
        int hTo = to.identityHash();

        if (hFrom < hTo) {
            first = from;
            second = to;
        } else if (hFrom > hTo) {
            first = to;
            second = from;
        } else {
            tieBreaker.lock();
            try {
                if (System.identityHashCode(from) < System.identityHashCode(to)) {
                    first = from;
                    second = to;
                } else {
                    first = to;
                    second = from;
                }
            } finally {
                tieBreaker.unlock();
            }
        }

        first.getLock().lock();
        try {
            second.getLock().lock();
            try {
                from.withdraw(amount);
                to.deposit(amount);
                System.out.println("Transferred " + amount + " from " + from + " to " + to);
            } finally {
                second.getLock().unlock();
            }
        } finally {
            first.getLock().unlock();
        }
    }
