import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;

class Orb {
    private String name;

    public Orb(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }
}

public class MagicalOrbVault {
    private final int capacity;
    private final Queue<Orb> vault;
    private final Semaphore availableOrbs;
    private final Semaphore availableSlots;

    public MagicalOrbVault(int capacity) {
        this.capacity = capacity;
        this.vault = new LinkedList<>();
        this.availableOrbs = new Semaphore(0);
        this.availableSlots = new Semaphore(capacity);
    }

    public void put(Orb orb) throws InterruptedException {
        availableSlots.acquire();
        synchronized (vault) {
            vault.add(orb);
        }
        availableOrbs.release();
    }

    public Orb take() throws InterruptedException {
        availableOrbs.acquire();
        Orb orb;
        synchronized (vault) {
            orb = vault.poll();
        }
        availableSlots.release();
        return orb;
    }

    public boolean isEmpty() {
        synchronized (vault) {
            return vault.isEmpty();
        }
    }

    public boolean isFull() {
        synchronized (vault) {
            return vault.size() == capacity;
        }
    }

    public static void main(String[] args) {
        MagicalOrbVault vault = new MagicalOrbVault(5);
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable sorcerer1 = () -> {
            try {
                for (int i = 0; i < 10; i++) {
                    Orb orb = new Orb("Orb " + i);
                    vault.put(orb);
                    System.out.println("Sorcerer 1 added " + orb.getName());
                    Thread.sleep(100);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable sorcerer2 = () -> {
            try {
                for (int i = 0; i < 10; i++) {
                    Orb orb = vault.take();
                    System.out.println("Sorcerer 2 retrieved " + orb.getName());
                    Thread.sleep(100);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        executor.execute(sorcerer1);
        executor.execute(sorcerer2);
        executor.shutdown();

        try {
            Thread.sleep(2000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Vault empty: " + vault.isEmpty());
        System.out.println("Vault full: " + vault.isFull());
    }
}

