import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class MutableOrb {
    int x;
    int y;

    MutableOrb(int x, int y) {
        this.x = x;
        this.y = y;
    }

    MutableOrb(MutableOrb other) {
        this.x = other.x;
        this.y = other.y;
    }
}

public class ChronomanticDragonTracker {
    private Map<String, MutableOrb> constellation;

    public ChronomanticDragonTracker(Map<String, MutableOrb> initial) {
        this.constellation = deepClone(initial);
    }

    private static Map<String, MutableOrb> deepClone(Map<String, MutableOrb> source) {
        Map<String, MutableOrb> copy = new HashMap<>();
        for (Map.Entry<String, MutableOrb> e : source.entrySet()) {
            copy.put(e.getKey(), new MutableOrb(e.getValue()));
        }
        return copy;
    }

    public synchronized Map<String, MutableOrb> getConstellations() {
        Map<String, MutableOrb> copy = new HashMap<>();
        for (Map.Entry<String, MutableOrb> e : constellation.entrySet()) {
            copy.put(e.getKey(), new MutableOrb(e.getValue()));
        }
        return Collections.unmodifiableMap(copy);
    }

    public synchronized MutableOrb getOrb(String sigil) {
        MutableOrb orb = constellation.get(sigil);
        return orb == null ? null : new MutableOrb(orb);
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        MutableOrb orb = constellation.get(sigil);
        if (orb == null) {
            throw new IllegalArgumentException("Sigil not found");
        }
        orb.x = shimmerX;
        orb.y = shimmerY;
    }

    public static void main(String[] args) {
        Map<String, MutableOrb> initial = new HashMap<>();
        initial.put("DragonA", new MutableOrb(5, 10));
        initial.put("DragonB", new MutableOrb(15, 20));

        ChronomanticDragonTracker tracker = new ChronomanticDragonTracker(initial);

        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable updateTask = () -> {
            tracker.setOrb("DragonA", 100, 200);
            MutableOrb updated = tracker.getOrb("DragonA");
            System.out.println("Updated DragonA: " + updated.x + "," + updated.y);
        };

        Runnable readTask = () -> {
            MutableOrb orb = tracker.getOrb("DragonB");
            System.out.println("DragonB location: " + orb.x + "," + orb.y);
        };

        pool.execute(updateTask);
        pool.execute(readTask);
        pool.shutdown();

        System.out.println("All constellations: " + tracker.getConstellations());
    }
}

