import java.util.Random;

public class SummonChaosOrbs {

    static class Orb {
        private int mana;
        private final Object lock = new Object();

        public Orb(int mana) {
            this.mana = mana;
        }

        public void addMana(int amount) {
            synchronized (lock) {
                mana += amount;
            }
        }

        public boolean removeMana(int amount) {
            synchronized (lock) {
                if (mana >= amount) {
                    mana -= amount;
                    return true;
                }
                return false;
            }
        }

        public int getMana() {
            synchronized (lock) {
                return mana;
            }
        }
    }

    static class InsufficientManaException extends Exception {
        public InsufficientManaException(String message) {
            super(message);
        }
    }

    static class EtherealFlux {
        public static void transferEnergy(Orb from, Orb to, int amount) throws InsufficientManaException {
            if (from == to) return;

            Orb firstLock, secondLock;
            if (System.identityHashCode(from) < System.identityHashCode(to)) {
                firstLock = from;
                secondLock = to;
            } else {
                firstLock = to;
                secondLock = from;
            }

            synchronized (firstLock.lock) {
                synchronized (secondLock.lock) {
                    if (from.getMana() < amount) {
                        throw new InsufficientManaException("Insufficient mana in source orb");
                    }
                    from.removeMana(amount);
                    to.addMana(amount);
                }
            }
        }
    }

    static class FluxThread extends Thread {
        private final Orb[] orbs;
        private final Random random;

        public FluxThread(Orb[] orbs, Random random) {
            this.orbs = orbs;
            this.random = random;
        }

        @Override
        public void run() {
            for (int i = 0; i < 10; i++) {
                int orb1Index = random.nextInt(orbs.length);
                int orb2Index = random.nextInt(orbs.length);
                while (orb2Index == orb1Index) {
                    orb2Index = random.nextInt(orbs.length);
                }
                Orb orb1 = orbs[orb1Index];
                Orb orb2 = orbs[orb2Index];
                int manaShard = random.nextInt(10) + 1;
                try {
                    EtherealFlux.transferEnergy(orb1, orb2, manaShard);
                } catch (InsufficientManaException e) {
                    // Ignore
                }
            }
        }
    }

    public static void main(String[] args) {
        int numOrbs = 5;
        Orb[] orbs = new Orb[numOrbs];
        for (int i = 0; i < numOrbs; i++) {
            orbs[i] = new Orb(100);
        }

        Random random = new Random();
        FluxThread thread1 = new FluxThread(orbs, random);
        FluxThread thread2 = new FluxThread(orbs, random);

        thread1.start();
        thread2.start();

        try {
            thread1.join();
            thread2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        for (int i = 0; i < numOrbs; i++) {
            System.out.println("Orb " + i + " mana: " + orbs[i].getMana());
        }
    }
}

