import java.util.Random;

public class GoblinGoldShuffle {

    static class InsufficientGoldException extends Exception {
        public InsufficientGoldException(String message) {
            super(message);
        }
    }

    static class GoldClump {
        private int amount;

        public GoldClump(int amount) {
            this.amount = amount;
        }

        public int getAmount() {
            return amount;
        }
    }

    static class GoblinPouch {
        private int gold;
        private final Object lock = new Object();

        public GoblinPouch(int gold) {
            this.gold = gold;
        }

        public void addGold(int amount) {
            synchronized (lock) {
                gold += amount;
            }
        }

        public boolean hasGold(int amount) {
            synchronized (lock) {
                return gold >= amount;
            }
        }

        public void removeGold(int amount) {
            synchronized (lock) {
                gold -= amount;
            }
        }

        public int getGold() {
            synchronized (lock) {
                return gold;
            }
        }
    }

    static class SneakyTrade {
        public static void transferGold(GoblinPouch from, GoblinPouch to, GoldClump amount) throws InsufficientGoldException {
            if (from == to) return;

            Object firstLock, secondLock;
            if (System.identityHashCode(from) < System.identityHashCode(to)) {
                firstLock = from.lock;
                secondLock = to.lock;
            } else {
                firstLock = to.lock;
                secondLock = from.lock;
            }

            synchronized (firstLock) {
                synchronized (secondLock) {
                    if (from.hasGold(amount.getAmount())) {
                        from.removeGold(amount.getAmount());
                        to.addGold(amount.getAmount());
                    } else {
                        throw new InsufficientGoldException("Not enough gold");
                    }
                }
            }
        }
    }

    static class TradeThread extends Thread {
        private final GoblinPouch[] pouches;
        private final Random random;

        public TradeThread(GoblinPouch[] pouches, Random random) {
            this.pouches = pouches;
            this.random = random;
        }

        @Override
        public void run() {
            for (int i = 0; i < 10; i++) {
                int fromIdx = random.nextInt(pouches.length);
                int toIdx = random.nextInt(pouches.length);
                if (fromIdx == toIdx) continue;
                GoldClump clump = new GoldClump(random.nextInt(10) + 1);
                try {
                    SneakyTrade.transferGold(pouches[fromIdx], pouches[toIdx], clump);
                } catch (InsufficientGoldException e) {
                    // ignore
                }
            }
        }
    }

    public static void main(String[] args) {
        int pouchCount = 5;
        GoblinPouch[] pouches = new GoblinPouch[pouchCount];
        for (int i = 0; i < pouchCount; i++) {
            pouches[i] = new GoblinPouch(100);
        }

        Random random = new Random();
        TradeThread[] threads = new TradeThread[2];
        for (int i = 0; i < threads.length; i++) {
            threads[i] = new TradeThread(pouches, random);
            threads[i].start();
        }

        for (TradeThread t : threads) {
            try {
                t.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        for (int i = 0; i < pouches.length; i++) {
            System.out.println("Pouch " + i + ": " + pouches[i].getGold());
        }
    }
}

