import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class EnchantedCAS {
    private volatile int dustLevel;

    public EnchantedCAS(int initialDustLevel) {
        this.dustLevel = initialDustLevel;
    }

    public int compareAndSwap(int expected, int newValue) {
        int originalValue;
        do {
            originalValue = dustLevel;
            if (originalValue == expected) {
                if (newValue != originalValue) {
                    dustLevel = newValue;
                }
                return originalValue;
            }
        } while (originalValue == expected);
        return originalValue;
    }

    public int getDustLevel() {
        return dustLevel;
    }
}

class PixieDustCounter {
    private final EnchantedCAS enchantedCAS;

    public PixieDustCounter(int initialDustLevel) {
        this.enchantedCAS = new EnchantedCAS(initialDustLevel);
    }

    public int getDustLevel() {
        return enchantedCAS.getDustLevel();
    }

    public void sprinkle() {
        int currentDustLevel;
        int newDustLevel;
        do {
            currentDustLevel = enchantedCAS.getDustLevel();
            newDustLevel = currentDustLevel + 1;
        } while (enchantedCAS.compareAndSwap(currentDustLevel, newDustLevel) != currentDustLevel);
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        PixieDustCounter pixieDustCounter = new PixieDustCounter(0);
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable sprinkleTask = () -> {
            for (int i = 0; i < 100000; i++) {
                pixieDustCounter.sprinkle();
            }
        };

        executor.execute(sprinkleTask);
        executor.execute(sprinkleTask);

        executor.shutdown();

        while (!executor.isTerminated()) {
            Thread.sleep(1);
        }

        System.out.println("Final Dust Level: " + pixieDustCounter.getDustLevel());
    }
}

