import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class Animal {
    private final String species;
    private final String gender;

    public Animal(String species, String gender) {
        this.species = species;
        this.gender = gender;
    }

    public String getSpecies() {
        return species;
    }

    public String getGender() {
        return gender;
    }
}

class AnimalPair {
    private final Animal first;
    private final Animal second;

    public AnimalPair(Animal first, Animal second) {
        this.first = first;
        this.second = second;
    }
}

class Ark {
    private final List<AnimalPair> pairs = new ArrayList<>();

    public synchronized void addPair(AnimalPair pair) {
        pairs.add(pair);
    }

    public int getPairCount() {
        return pairs.size();
    }
}

public class Main {
    enum Gender {
        MALE, FEMALE
    }

    public static void main(String[] args) throws InterruptedException {
        List<Animal> animals = Arrays.asList(
            new Animal("Dog", Gender.MALE.toString()),
            new Animal("Dog", Gender.FEMALE.toString()),
            new Animal("Cat", Gender.MALE.toString()),
            new Animal("Cat", Gender.FEMALE.toString()),
            new Animal("Dog", Gender.MALE.toString()),
            new Animal("Dog", Gender.FEMALE.toString())
        );

        Ark ark = new Ark();

        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.submit(() -> loadTheArk(animals, ark));
        executor.shutdown();

        while (!executor.isTerminated()) {
            Thread.sleep(10);
        }

        System.out.println("Number of valid pairs: " + ark.getPairCount());
    }

