        Collections.sort(animals, Comparator.comparing(Animal::getSpecies).thenComparing(Animal::getGender));

        int i = 0;
        while (i < animals.size() - 1) {
            Animal a1 = animals.get(i);
            Animal a2 = animals.get(i + 1);
            if (a1.getSpecies().equals(a2.getSpecies()) && !a1.getGender().equals(a2.getGender())) {
                ark.addPair(new AnimalPair(a1, a2));
                i += 2;
            } else {
                i++;
            }
        }
    }
}

