import java.math.BigInteger;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class FactorCache {
    private final BigInteger number;
    private final BigInteger[] factors;

    public FactorCache(BigInteger number, BigInteger[] factors) {
        this.number = number;
        this.factors = factors;
    }

    public BigInteger[] getFactors(BigInteger input) {
        if (input.equals(number)) {
            return factors.clone();
        }
        return null;
    }
}

class FactorCalculator implements Runnable {
    private final BigInteger number;

    public FactorCalculator(BigInteger number) {
        this.number = number;
    }

    @Override
    public void run() {
        BigInteger[] factors = calculateFactors(number);
        FactorCache cache = new FactorCache(number, factors);
        System.out.println("Cached factors for " + number + ": " + java.util.Arrays.toString(factors));
        BigInteger[] retrievedFactors = cache.getFactors(number);
        System.out.println("Retrieved factors for " + number + ": " + java.util.Arrays.toString(retrievedFactors));
    }

