import java.util.Set;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class CosmicCats {
    private final Set<String> identifiers;

    private CosmicCats(Set<String> source) {
        Set<String> copy = new LinkedHashSet<String>(source);
        this.identifiers = Collections.unmodifiableSet(copy);
    }

    public static CosmicCats ofCosmicCats() {
        Set<String> mutableSource = new LinkedHashSet<String>();
        mutableSource.add("Whiskers");
        mutableSource.add("Paws");
        mutableSource.add("Claw");
        return new CosmicCats(mutableSource);
    }

    public boolean isCat(String identifier) {
        return identifiers.contains(identifier);
    }

    public String display() {
        return new ArrayList<String>(identifiers).toString();
    }

    public static void main(String[] args) throws Exception {
        final CosmicCats cosmicCats = CosmicCats.ofCosmicCats();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Callable<String> lookupTaskOne = new Callable<String>() {
            public String call() {
                StringBuilder result = new StringBuilder();
                result.append(Thread.currentThread().getName());
                result.append(" contains Whiskers=");
                result.append(cosmicCats.isCat("Whiskers"));
                result.append(", contains Shadow=");
                result.append(cosmicCats.isCat("Shadow"));
                return result.toString();
            }
        };

        Callable<String> lookupTaskTwo = new Callable<String>() {
            public String call() {
                StringBuilder result = new StringBuilder();
                result.append(Thread.currentThread().getName());
                result.append(" contains Paws=");
                result.append(cosmicCats.isCat("Paws"));
                result.append(", contains Claw=");
                result.append(cosmicCats.isCat("Claw"));
                return result.toString();
            }
        };

        List<Callable<String>> tasks = Arrays.asList(lookupTaskOne, lookupTaskTwo);
        List<Future<String>> futures = executor.invokeAll(tasks);

        for (Future<String> future : futures) {
            System.out.println(future.get());
        }

        System.out.println(cosmicCats.display());
        executor.shutdown();
    }
}

