import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

public class CosmicCats {
    private final Set<String> catIdentifiers;

    public CosmicCats() {
        Set<String> tempSet = new HashSet<>();
        tempSet.add("Whiskers");
        tempSet.add("Paws");
        tempSet.add("Claw");
        this.catIdentifiers = Collections.unmodifiableSet(tempSet);
    }

    public boolean isCat(String identifier) {
        return catIdentifiers.contains(identifier);
    }

    public String displayCats() {
        return catIdentifiers.stream()
                .sorted()
                .collect(Collectors.joining(", ", "[", "]"));
    }

    public static void main(String[] args) {
        CosmicCats cosmicCats = new CosmicCats();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(new Runnable() {
            public void run() {
                System.out.println("Thread 1: Checking identifiers...");
                System.out.println("Is 'Whiskers' a cat? " + cosmicCats.isCat("Whiskers"));
                System.out.println("Is 'Fluffy' a cat? " + cosmicCats.isCat("Fluffy"));
                System.out.println("Is 'Paws' a cat? " + cosmicCats.isCat("Paws"));
            }
        });

        executor.submit(new Runnable() {
            public void run() {
                System.out.println("Thread 2: Displaying all cats...");
                System.out.println("All Cosmic Cats: " + cosmicCats.displayCats());
                System.out.println("Is 'Claw' a cat? " + cosmicCats.isCat("Claw"));
            }
        });

        executor.shutdown();
        try {
            executor.awaitTermination(1, TimeUnit.MINUTES);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Main thread: Final display - " + cosmicCats.displayCats());
    }
}

